INSERT INTO `wp_alm` VALUES (1,'default','<li <?php if (!has_post_thumbnail()) { ?> class=\"no-img\"<?php } ?>><?php if ( has_post_thumbnail() ) { the_post_thumbnail(array(150,150));}?><h3><a href=\"<?php the_permalink(); ?>\" title=\"<?php the_title(); ?>\"><?php the_title(); ?></a></h3><p class=\"entry-meta\"><?php the_time(\"F d, Y\"); ?></p><?php the_excerpt(); ?></li>','default','2.14.0');
INSERT INTO `wp_alm_unlimited` VALUES (1,'template_1','<?php \n$name = get_field(\'first_name\').\' \'.get_field(\'last_name\');\n$title = get_field( \'title\' );\n$gl_title = get_field( \'gl_area\' );\n$city = get_field( \'city\' );\n\n$job_title = get_field(\'job_title\'); \n$featured_image = get_the_post_thumbnail_url( null, \'full\' );\n\n?>\n    <div class=\"member-ctn\">\n\n<a class=\"member-link <?php echo get_field(\'location\')?> <?php echo $job_title[\'value\'] ?>\" <?php if(get_field(\'external_link\')):?> href=\"<?php echo get_field(\'external_link\')?>\" target=\"_blank\" <?php else:?>\n    style=\"pointer-events:none;\" <?php endif;?>>\n        <div class=\"mem-img\">\n            <img src=\"<?php if($featured_image){echo $featured_image ;}else{echo  site_url() .\"/wp-content/uploads/2022/01/TAXAND_Redesign_OurTeam_Headshot_Placeholder@2x.jpeg\";}?>\"\n                alt=\"<?php echo $name;?>\" />\n        </div>\n        <div class=\"mem-text\">\n            <p><strong><?php echo get_the_title(); ?></strong></p>\n            <p><?php echo $title;?></p>\n        <p><?php echo implode( \' & \', $city );?></p>\n        </div>\n\n</a>    </div>','Team Members','2.5.8');
INSERT INTO `wp_alm_unlimited` VALUES (2,'template_2','<div class=\"col-md-4\">\n        <div class=\"insight-block\">\n          <div class=\"insight-img\" style=\"background-image:url(<?php echo get_field(\'home-thumb\'); ?>)\">\n          </div>           <span class=\"post-date d-inline\"><?php echo get_the_date(); ?> \n    <?php foreach ( get_the_terms( get_the_ID(), \'filter_region\' ) as $tax ) {\n    echo \'  / \' . __( $tax->name ) . \'</span>\';\n}\n        ?>\n               \n          <h3><?php  echo wp_trim_words( get_the_title(), 10, \'...\' );?></h3>\n          <div class=\"short-border\"></div>\n                  <p><?php  echo wp_trim_words( get_field(\'home-excerpt\'), 20, \'...\' );?></p>\n\n          <a class=\"plain-btn\" href=\"<?php echo get_permalink()?>\">Read More <i class=\"fas fa-caret-right\"></i></a>\n        </div>\n      </div>','Thought Leadership','2.5.8');
INSERT INTO `wp_alm_unlimited` VALUES (3,'template_3','<div class=\"col-md-4\">\n        <div class=\"insight-block\">\n          <div class=\"insight-img\" style=\"background-image:url(<?php echo get_field(\'home-thumb\'); ?>)\">\n          </div>\n        <span class=\"post-date\"><?php echo get_the_date(); ?></span>\n     \n          <h3 class=\"test\"><?php  echo wp_trim_words( get_the_title(), 10, \'...\' );?></h3>\n          <div class=\"short-border\"></div>\n       <?php foreach ( get_the_terms( get_the_ID(), \'filter_region\' ) as $tax ) {\n    echo \'<p class=\"post-term\">\' . __( $tax->name ) . \'</p>\';\n}\n        ?>\n\n          <a class=\"plain-btn\" href=\"<?php echo get_permalink()?>\">Read More <i class=\"fas fa-caret-right\"></i></a>\n        </div>\n      </div>','Events','2.5.8');
INSERT INTO `wp_alm_unlimited` VALUES (4,'template_4','<div class=\"col-md-4\">\n        <div class=\"insight-block\">\n          <div class=\"insight-img\" style=\"background-image:url(<?php echo get_field(\'home-thumb\'); ?>)\">\n          </div>\n                <span class=\"post-date\"><?php echo get_the_date(); ?></span>\n\n          <h3><?php  echo wp_trim_words( get_the_title(), 10, \'...\' );?></h3>\n          <div class=\"short-border\"></div>\n          <p><?php  echo wp_trim_words( get_field(\'home-excerpt\'), 20, \'...\' );?></p>\n          <a class=\"plain-btn\" href=\"<?php echo get_permalink()?>\">Read More <i class=\"fas fa-caret-right\"></i></a>\n        </div>\n      </div>','Template #4','2.5.8');
INSERT INTO `wp_alm_unlimited` VALUES (5,'template_5','<div class=\"col-sm-6 col-md-4\">\n      <div class=\"news-block-2 ms\">\n        <div class=\"news-block-feature\"><a href=\"<?php the_field(\'source\')?>\">\n          <h1>\n            <?php the_field(\'client\'); ?>\n          </h1>\n          <img src=\"<?php the_field(\'home-thumb\'); ?>\"/></a></div>\n\n        <div class=\"news-block-2z\">\n          <div class=\"date\"><?php echo get_the_date(); ?> /\n            <?php if( get_field(\'city\') ): ?>\n            <?php the_field(\'city\'); ?>\n            <?php endif; ?>\n          </div>\n          <h3><?php the_field(\'client2\'); ?></h3>\n          <p><strong>Subindustries: </strong><br>\n            <?php the_field(\'subindustries\'); ?><br><br>\n            <strong>Services Provided: </strong><br>\n            <?php the_field(\'services\'); ?>\n            </p>\n        </div>\n      </div>\n    </div>','Template #5','2.5.8');
INSERT INTO `wp_alm_unlimited` VALUES (6,'template_6','<div class=\"col-md-4\">\n        <div class=\"insight-block\">\n          <div class=\"insight-img\" style=\"background-image:url(<?php echo get_field(\'home-thumb\'); ?>)\">\n          </div>\n                <span class=\"post-date\"><?php echo get_the_date(); ?></span>\n          <h3><?php  echo wp_trim_words( get_the_title(), 10, \'...\' );?></h3>\n          <div class=\"short-border\"></div>\n          <p><?php  echo wp_trim_words( get_field(\'home-excerpt\'), 20, \'...\' );?></p>\n          <a class=\"plain-btn\" href=\"<?php echo get_permalink()?>\">Read More <i class=\"fas fa-caret-right\"></i></a>\n        </div>\n      </div>','Trends & Highlights','2.5.8');
