INSERT INTO `wp_options` VALUES (555330,'alm_filter_filter_deals','s:1178:\"a:8:{s:2:\"id\";s:12:\"filter_deals\";s:5:\"style\";s:6:\"button\";s:12:\"reset_button\";b:1;s:18:\"reset_button_label\";s:0:\"\";s:11:\"button_text\";s:5:\"APPLY\";s:12:\"date_created\";i:1662118667;s:13:\"date_modified\";i:1662122416;s:7:\"filters\";a:4:{i:0;a:8:{s:3:\"key\";s:8:\"taxonomy\";s:10:\"field_type\";s:6:\"select\";s:8:\"taxonomy\";s:11:\"filter_year\";s:17:\"taxonomy_operator\";s:2:\"IN\";s:21:\"default_select_option\";s:4:\"Year\";s:5:\"title\";s:0:\"\";s:10:\"show_count\";b:0;s:14:\"section_toggle\";b:0;}i:1;a:8:{s:3:\"key\";s:8:\"taxonomy\";s:10:\"field_type\";s:6:\"select\";s:8:\"taxonomy\";s:15:\"filter_services\";s:17:\"taxonomy_operator\";s:2:\"IN\";s:21:\"default_select_option\";s:8:\"Services\";s:5:\"title\";s:0:\"\";s:10:\"show_count\";b:0;s:14:\"section_toggle\";b:0;}i:2;a:8:{s:3:\"key\";s:8:\"taxonomy\";s:10:\"field_type\";s:6:\"select\";s:8:\"taxonomy\";s:15:\"filter_industry\";s:17:\"taxonomy_operator\";s:2:\"IN\";s:21:\"default_select_option\";s:8:\"Industry\";s:5:\"title\";s:0:\"\";s:10:\"show_count\";b:0;s:14:\"section_toggle\";b:0;}i:3;a:7:{s:3:\"key\";s:8:\"taxonomy\";s:10:\"field_type\";s:6:\"select\";s:8:\"taxonomy\";s:14:\"filter_country\";s:17:\"taxonomy_operator\";s:2:\"IN\";s:5:\"title\";s:0:\"\";s:10:\"show_count\";b:0;s:14:\"section_toggle\";b:0;}}}\";','yes');
