INSERT INTO `wp_options` VALUES (553167,'page_scroll_to_id_instances','a:1:{s:17:\"mPS2id_instance_0\";a:35:{s:8:\"selector\";a:10:{s:5:\"value\";s:28:\"a[href*=\'#\']:not([href=\'#\'])\";s:6:\"values\";N;s:2:\"id\";s:28:\"page_scroll_to_id_0_selector\";s:10:\"field_type\";s:4:\"text\";s:5:\"label\";s:11:\"Selector(s)\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:662:\"Set the links (in the form of <a href=\"http://www.w3.org/TR/css3-selectors/\" target=\"_blank\">CSS selectors</a>) that will scroll the page when clicked (default value: any link with a non-empty hash (<code>#</code>) value in its URL) <br /><small>In addition to selectors above, the plugin is enabled automatically on links (or links contained within elements) with class <code>ps2id</code></small> <br /><small><a class=\"button button-small mPS2id-show-option-common-values\" href=\"#\">Show common values</a><span>For all links: <code>a[href*=\'#\']:not([href=\'#\'])</code><br />For menu links only: <code>.menu-item a[href*=\'#\']:not([href=\'#\'])</code></span></small>\";s:7:\"wrapper\";N;}s:21:\"autoSelectorMenuLinks\";a:10:{s:5:\"value\";s:4:\"true\";s:6:\"values\";N;s:2:\"id\";s:41:\"page_scroll_to_id_0_autoSelectorMenuLinks\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:30:\"Enable on WordPress Menu links\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:185:\"Automatically enable the plugin on custom links (containing <code>#</code> in their URL) created in Appearance &rarr; Menus <br /><small>Requires WordPress version 3.6 or higher</small>\";s:7:\"wrapper\";s:8:\"fieldset\";}s:15:\"excludeSelector\";a:10:{s:5:\"value\";s:166:\"a[href^=\'#tab-\'], a[href^=\'#tabs-\'], a[data-toggle]:not([data-toggle=\'tooltip\']), a[data-slide], a[data-vc-tabs], a[data-vc-accordion], a.screen-reader-text.skip-link\";s:6:\"values\";N;s:2:\"id\";s:35:\"page_scroll_to_id_0_excludeSelector\";s:10:\"field_type\";s:4:\"text\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";s:22:\"selectors are excluded\";s:11:\"description\";s:512:\"Set the links (in the form of <a href=\"http://www.w3.org/TR/css3-selectors/\" target=\"_blank\">CSS selectors</a>) that will be excluded from plugin&apos;s selectors (the plugin will not hanlde these links) <br /><small><a class=\"button button-small mPS2id-show-option-common-values\" href=\"#\">Show common values</a><span><code>a[href^=\'#tab-\'], a[href^=\'#tabs-\'], a[data-toggle]:not([data-toggle=\'tooltip\']), a[data-slide], a[data-vc-tabs], a[data-vc-accordion], a.screen-reader-text.skip-link</code></span></small>\";s:7:\"wrapper\";N;}s:11:\"scrollSpeed\";a:10:{s:5:\"value\";i:800;s:6:\"values\";N;s:2:\"id\";s:31:\"page_scroll_to_id_0_scrollSpeed\";s:10:\"field_type\";s:12:\"text-integer\";s:5:\"label\";s:15:\"Scroll duration\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";s:12:\"milliseconds\";s:11:\"description\";s:99:\"Scroll animation duration (i.e. scrolling speed) in milliseconds (1000 milliseconds equal 1 second)\";s:7:\"wrapper\";N;}s:15:\"autoScrollSpeed\";a:10:{s:5:\"value\";s:5:\"false\";s:6:\"values\";N;s:2:\"id\";s:35:\"page_scroll_to_id_0_autoScrollSpeed\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:30:\"Auto-adjust scrolling duration\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:104:\"Enable to let the plugin fine-tune scrolling duration/speed according to target and page scroll position\";s:7:\"wrapper\";s:8:\"fieldset\";}s:12:\"scrollEasing\";a:10:{s:5:\"value\";s:14:\"easeInOutQuint\";s:6:\"values\";s:406:\"linear,swing,easeInQuad,easeOutQuad,easeInOutQuad,easeInCubic,easeOutCubic,easeInOutCubic,easeInQuart,easeOutQuart,easeInOutQuart,easeInQuint,easeOutQuint,easeInOutQuint,easeInExpo,easeOutExpo,easeInOutExpo,easeInSine,easeOutSine,easeInOutSine,easeInCirc,easeOutCirc,easeInOutCi