INSERT INTO `wp_options` VALUES (559170,'_transient_ctf__NIck_Alvarez673','[{\"user\":{\"name\":\"Nick Alvarez\",\"description\":\"Managing Director & National Practice Leader, @alvarezmarsal Private Equity Performance Improvement; Loves good wine, golf & @SoulCycle; Posts are my own views.\",\"statuses_count\":2203,\"followers_count\":482,\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"A view made for a movie. Always gorgeous. #HogsHead #Golf  #WorkHardPlayHard \",\"id_str\":\"1574788212232519682\",\"created_at\":\"Tue Sep 27 15:49:02 +0000 2022\",\"retweet_count\":0,\"favorite_count\":1,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/FdrFiFjXEAA_uyG.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":432,\"h\":226,\"resize\":\"fit\"},\"small\":{\"w\":432,\"h\":226,\"resize\":\"fit\"},\"large\":{\"w\":432,\"h\":226,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"It was great to see all of the @alvarezmarsal #TransactionAdvisory Group\'s leaders have the chance to get together in Spain. Glad I could be a part of it along with our A&amp;M co-founders! @PaulAversano @TonyAlvarezIII #LikeWhatYouDo #LikeWhoYouDoItWith \",\"id_str\":\"1574549635506573313\",\"created_at\":\"Tue Sep 27 00:01:01 +0000 2022\",\"retweet_count\":0,\"favorite_count\":5,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/FdnsjFlWAAETbdH.jpg\",\"type\":\"photo\",\"sizes\":{\"large\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":356,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Fine wines and finer times with my family at Lake Como #WineLover \",\"id_str\":\"1573322563639545857\",\"created_at\":\"Fri Sep 23 14:45:04 +0000 2022\",\"retweet_count\":0,\"favorite_count\":1,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/FdWQiJeWQAIf15e.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"},\"large\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":356,\"resize\":\"fit\"}}}]}}]','no');
