INSERT INTO `wp_options` VALUES (559172,'_transient_ctf__PaulAversano3','[{\"user\":{\"name\":\"Paul Aversano\",\"description\":\"Global Practice Leader, @alvarezmarsal Transaction Advisory Group; BoD @PowerPlayNYC @answerthecall; Enjoys family & golf; AKA #006; Posts are my own views.\",\"statuses_count\":9365,\"followers_count\":1098,\"screen_name\":\"PaulAversano\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/848983432956956674\\/s26MDoI8_normal.jpg\",\"utc_offset\":null},\"text\":\"RT @alvarezmarsal: With offices in India, A&amp;M\\u2019s Global Transaction Advisory team is well-positioned to serve our clients throughout Asia. O\\u2026\",\"id_str\":\"1574772523010506753\",\"created_at\":\"Tue Sep 27 14:46:42 +0000 2022\",\"retweet_count\":1,\"favorite_count\":0,\"retweeted_status\":{\"user\":{\"name\":\"Alvarez & Marsal\",\"screen_name\":\"alvarezmarsal\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1546529249032560641\\/dxkYNK4m_normal.png\",\"utc_offset\":null},\"text\":\"With offices in India, A&amp;M\\u2019s Global Transaction Advisory team is well-positioned to serve our clients throughout Asia. Our practice combines operational, functional &amp; industry expertise to maximize every transaction\\u2019s value. https:\\/\\/t.co\\/jMYAXrTmnT #AMon #TransactionAdvisory \",\"id_str\":\"1574760828380782594\",\"created_at\":\"Tue Sep 27 14:00:13 +0000 2022\",\"retweet_count\":1,\"favorite_count\":1,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/FdqsoBdWYAM5tWB.jpg\",\"type\":\"photo\",\"sizes\":{\"large\":{\"w\":1200,\"h\":627,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1200,\"h\":627,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":355,\"resize\":\"fit\"}}}]},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/bddy.me\\/3rcoOba\"}]}}},{\"user\":{\"name\":\"Paul Aversano\",\"screen_name\":\"PaulAversano\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/848983432956956674\\/s26MDoI8_normal.jpg\",\"utc_offset\":null},\"text\":\"Hiring and retaining talent can make or break a company. It truly takes talent to seek talent. Luckily, I have the best people for the job, and I\'m so grateful for all of them! #LikeWhatYouDo #LikeWhoYouDoItWith @AlvarezMarsal \",\"id_str\":\"1574499808764739608\",\"created_at\":\"Mon Sep 26 20:43:01 +0000 2022\",\"retweet_count\":0,\"favorite_count\":1,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/Fdm_OvcXwAQIcg7.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":356,\"resize\":\"fit\"},\"medium\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Paul Aversano\",\"screen_name\":\"PaulAversano\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/848983432956956674\\/s26MDoI8_normal.jpg\",\"utc_offset\":null},\"text\":\"I never say \\\"no\\\" to some father-daughter time! #GirlDad #Throwback \",\"id_str\":\"1574499806441095197\",\"created_at\":\"Mon Sep 26 20:43:01 +0000 2022\",\"retweet_count\":0,\"favorite_count\":1,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/Fdm_OsRXwAAHGta.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]}}]','no');
