INSERT INTO `wp_options` VALUES (559174,'_transient_ctf__Ernie_R_Perez3','[{\"user\":{\"name\":\"Ernie Perez\",\"description\":\"Global Practice Leader, @alvarezmarsal Taxand;Transaction Advisory Tax, Domestic\\/Cross-Border Acquisitions, Divestitures, Reorgs @universityofga @miamilawschool\",\"statuses_count\":3137,\"followers_count\":299,\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1504279215096713219\\/GiZ7yZL7_normal.jpg\",\"utc_offset\":null},\"text\":\"#Throwback to our @AlvarezMarsal #Taxand NYC Office Summer Social at the beginning of the sunny season! As you can see, we take our core value of fun very seriously, so it\\u2019s always easy to #LikeWhatYouDo and #LikeWhoYouDoItWith! #HappyHour \",\"id_str\":\"1574774622326751232\",\"created_at\":\"Tue Sep 27 14:55:02 +0000 2022\",\"retweet_count\":0,\"favorite_count\":0,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/Fdq5LD8XwAgrCJZ.jpg\",\"type\":\"photo\",\"sizes\":{\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Ernie Perez\",\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1504279215096713219\\/GiZ7yZL7_normal.jpg\",\"utc_offset\":null},\"text\":\"W\\/ @Tesla seeking to move its production of rechargeable cells from Germany to the US in order to qualify for #tax credits, it seems that the new #InflationReductionAct is succeeding in revamping the #ElectricVehicle industry. @WSJ: https:\\/\\/t.co\\/HJ7lUR5aiq @rfelliott @MikeColias\",\"id_str\":\"1574416006239371266\",\"created_at\":\"Mon Sep 26 15:10:01 +0000 2022\",\"retweet_count\":0,\"favorite_count\":1,\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/on.wsj.com\\/3xzLCVU\"}]}},{\"user\":{\"name\":\"Ernie Perez\",\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1504279215096713219\\/GiZ7yZL7_normal.jpg\",\"utc_offset\":null},\"text\":\"One of my favorite pics of me and Kate - Happy #NationalDaughtersDay! \",\"id_str\":\"1574054374971686914\",\"created_at\":\"Sun Sep 25 15:13:02 +0000 2022\",\"retweet_count\":0,\"favorite_count\":3,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/FdgqHIGXkAIgSL2.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"small\":{\"w\":680,\"h\":356,\"resize\":\"fit\"},\"medium\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"},\"large\":{\"w\":1200,\"h\":628,\"resize\":\"fit\"}}}]}}]','no');
