INSERT INTO `wp_postmeta` VALUES (11709,641,'_header-image','field_58911460d81fb');
INSERT INTO `wp_postmeta` VALUES (11710,641,'header-title','Global Regulation Clouded After Trump and Brexit');
INSERT INTO `wp_postmeta` VALUES (11711,641,'_header-title','field_5891147bd81fc');
