INSERT INTO `wp_postmeta` VALUES (95362,2692,'header-title','Infrastructure Pulse Europe Q2 2020');
INSERT INTO `wp_postmeta` VALUES (95363,2692,'_header-title','field_588bc29fc9f7b');
INSERT INTO `wp_postmeta` VALUES (95364,2692,'header-sub-title','');
INSERT INTO `wp_postmeta` VALUES (95365,2692,'_header-sub-title','field_588bc2c7c9f7c');
