INSERT INTO `wp_postmeta` VALUES (95763,2723,'_tl-post-header','field_589ce8a44b9e2');
INSERT INTO `wp_postmeta` VALUES (95764,2723,'tl-post-content','Is opportunity hiding underneath the economic rubble of COVID-19? Richard Chen, Managing Director; Dawn Duong, Senior Director; and Christina Cheang, Senior Manager; with Alvarez &amp; Marsal’s Global Transaction Advisory Group, say yes. In the “Singapore: Opportunities and risks in the context of COVID-19” report they explain why and discuss:\r\n<ul>\r\n 	<li>Singapore’s economic structure and the drivers behind the country’s economic success despite having limited natural resources and small population</li>\r\n 	<li>Singapore’s track record of delivering on the government’s economic development goals and drive towards higher value</li>\r\n 	<li>The six dimensions for evaluating the impact of COVID-19 on the general economy and within specific sectors</li>\r\n 	<li>Newly identified economic opportunities, and associated risks, in the Semiconductor and Chemicals sectors</li>\r\n 	<li>How Singapore’s strong IP protection, skilled workforce and stable government positions the region to benefit from Industry 4.0</li>\r\n</ul>\r\nThe socio-economic challenges, international trade opportunities and value-generating industry sectors embedded in the country\r\n\r\n<a href=\"https://www.alvarezandmarsal.com/sites/default/files/115470_tag_sgp-se_asia_market_pov_final_1.pdf\" target=\"_blank\" rel=\"noopener\">Read the Report Overview</a>\r\n\r\n<a href=\"https://www.alvarezandmarsal.com/content/singapore-report-opportunities-and-risks-context-covid-19\" target=\"_blank\" rel=\"noopener\">Download the Full Report</a>');
INSERT INTO `wp_postmeta` VALUES (171967,2723,'_oembed_b27fd35dc2a42c5da8f4c7a578197c08','{{unknown}}');
