INSERT INTO `wp_postmeta` VALUES (124368,3313,'region_info_0_main_text_box','<h1>OUR PRACTICE AND LOCATIONS</h1>\r\n                  <p>A&M’s India Transaction Advisory Group provides investors and lenders the answers needed to get the deal done. We combine our firm’s deep operational, industry and accounting resources to assess key deal drivers and focus on the root cause of any critical deal issues.<br/>\r\n<br/>\r\nAs the largest transaction advisory practice outside the Big Four, our integrated teams help private equity, sovereign wealth funds, family offices and hedge funds as well as corporate acquirers unlock value across the investment lifecycle.<br/>\r\n<br/>\r\nThere are 100 transaction advisory focused professionals in India who have extensive experience across multiple sectors and geographies including South East Asia, SAARC, Middle East and Africa.</p>\r\n                  <a href=\"http://am-globaltag/team/\">\r\n                  <div class=\"sglv4-btn\">MEET OUR TEAM</div>\r\n                  </a><a href=\"http://am-globaltag/what-we-do/\">\r\n                  <div class=\"sglv4-btn\">MORE ON OUR GLOBAL PRACTICE</div>\r\n                  </a><a href=\"http://am-globaltag/global-leadership/\">\r\n                  <div class=\"sglv4-btn\">SEE ALL GLOBAL LOCATIONS</div>\r\n                  </a>');
INSERT INTO `wp_postmeta` VALUES (124369,3313,'_region_info_0_main_text_box','field_60be999013aea');
INSERT INTO `wp_postmeta` VALUES (124370,3313,'region_info_0_side_text_box','<div class=\"sglv4-cta\"><img class=\"sglv4-img\" src=\"http://am-globaltag/wp-content/themes/bones/images/ico-sglv1.svg\">\r\n<p>Ex-Big Four CPA & Chartered Accountants, Ex-Premier Strategy Professionals & Ex-Operators</p>\r\n</div>\r\n<div class=\"sglv4-cta\"><img class=\"sglv4-img\" src=\"http://am-globaltag/wp-content/themes/bones/images/ico-sglv2.svg\">\r\n<p>Senior Led Teams</p>\r\n</div>\r\n<div class=\"sglv4-cta\"><img class=\"sglv4-img\" src=\"http://am-globaltag/wp-content/themes/bones/images/ico-sglv3.svg\">\r\n<p>One Office in a Major City in India</p>\r\n</div>');
