INSERT INTO `wp_postmeta` VALUES (148786,2929,'team_intro','Global Transaction Advisory Group has close to 590 transaction advisory professionals in 26 offices globally. Our professionals are former Big Four CPA/Chartered Accountants. We have senior teams throughout United States, Latin America (Brazil and Mexico), Europe (United Kingdom, Germany, Netherlands, Nordics, France, Sweden, Switzerland, Spain, Italy), Middle East (Dubai and Riyadh), India (Mumbai) and South East Asia (Hong Kong, Shanghai, Beijing, Singapore).');
