INSERT INTO `wp_postmeta` VALUES (148788,2929,'meet_paul_cta_quote','“Anywhere around the world, A&M is M&A. Our Alvarez & Marsal Global Transaction Advisory Group is constantly at the forefront of cross-border deal making delivering maximum value to our clients and partners across the investment lifecycle.”');
