INSERT INTO `wp_postmeta` VALUES (171336,3625,'intro_text','A&M Data Intelligence Gateway (A&M DIG) takes unstructured government data, and when integrated with A&M’s deep operational, industry and functional expertise, creates private and public company insights that were previously unobtainable.');
INSERT INTO `wp_postmeta` VALUES (171337,3625,'_intro_text','field_630bc92b71847');
INSERT INTO `wp_postmeta` VALUES (171338,3625,'video_url','https://vimeo.com/629500653');
INSERT INTO `wp_postmeta` VALUES (171339,3625,'_video_url','field_630bc94871849');
INSERT INTO `wp_postmeta` VALUES (171340,3625,'our_differentiators_list','<ul>\r\n 	<li>A&amp;M DIG uses <strong>government data,</strong> ensuring it is <strong>reliable</strong> and updated on a consistent basis.</li>\r\n 	<li>A&amp;M DIG leverages <strong>A&amp;M operational and functional experts</strong> across industries who are on the ground and have first-hand <strong>insight</strong> into evolving market dynamics to determine additional data points needed to make the best investment decisions.</li>\r\n 	<li>A&amp;M DIG creates a <strong>customized dashboard</strong> that enables M&amp;A professionals to filter and sort through data such as <strong>company size, growth trajectory, company ownership</strong> and other meaningful data points determined by you to discover the best opportunities.</li>\r\n</ul>');
INSERT INTO `wp_postmeta` VALUES (171341,3625,'_our_differentiators_list','field_630bc9717184b');
INSERT INTO `wp_postmeta` VALUES (171342,3625,'our_differentiators_image','4585');
INSERT INTO `wp_postmeta` VALUES (171343,3625,'_our_differentiators_image','field_630bc9b27184c');
INSERT INTO `wp_postmeta` VALUES (171344,3625,'dig_team_members','2');
INSERT INTO `wp_postmeta` VALUES (171345,3625,'_dig_team_members','field_630bca627184e');
INSERT INTO `wp_postmeta` VALUES (171346,3625,'dig_team_text','A&M’s Data Intelligence Gateway (A&M DIG) team combines broad professional expertise with operational and functional knowledge to provide private equity companies with data from which to make better informed deal decisions. Connect with our team to <br class=\"d-none d-md-inline\">learn more.');
INSERT INTO `wp_postmeta` VALUES (171347,3625,'_dig_team_text','field_630bcaeb71852');
