INSERT INTO `wp_postmeta` VALUES (174852,4753,'region_info_0_main_text_box','The Global A&M Transaction Advisory Group in Europe and the Middle East supports investors in finding the answers that enable them to get the deal done. We combine our firm’s operational, industry and functional expertise with Big Four quality transaction services expertise to assess the key drivers and focus on the root cause of critical deal issues. Our team operates seamlessly cross-border providing clients consistent and flawless quality service. We have senior led teams in United Kingdom, France, Germany, Netherlands, Sweden, Switzerland, Spain, Italy and the United Arab Emirates that have extensive experience in supporting transactions across Europe and the Middle East in multiple sectors.\r\n\r\nOur integrated global teams service private equity, sovereign wealth funds, hedge funds, distress funds, multi-national corporations, investment banks and law firms to create value throughout the investment lifecycle.');
INSERT INTO `wp_postmeta` VALUES (174853,4753,'_region_info_0_main_text_box','field_63084094c95db');
INSERT INTO `wp_postmeta` VALUES (174854,4753,'region_info_0_side_text_box','<div class=\"sglv4-cta\"><img class=\"sglv4-img\" src=\"http://am-globaltag/wp-content/themes/bones/images/ico-sglv1.svg\">\r\n<p>Ex-Big Four CPA & Chartered Accountants, Ex-Premier Strategy Professionals & Ex-Operators</p>\r\n</div>\r\n<div class=\"sglv4-cta\"><img class=\"sglv4-img\" src=\"http://am-globaltag/wp-content/themes/bones/images/ico-sglv2.svg\">\r\n<p>Senior Led Teams</p>\r\n</div>\r\n<div class=\"sglv4-cta\"><img class=\"sglv4-img\" src=\"http://am-globaltag/wp-content/themes/bones/images/ico-sglv3.svg\">\r\n<p>Eleven Offices Serving All of Europe & Middle East</p>\r\n</div>');
