INSERT INTO `wp_postmeta` VALUES (176817,4771,'intro_text','A&M Data Intelligence Gateway (A&M DIG) takes unstructured government data, and when integrated with A&M’s deep operational, industry and functional expertise, creates private and public company insights that were previously unobtainable.');
INSERT INTO `wp_postmeta` VALUES (176818,4771,'_intro_text','field_630bc92b71847');
INSERT INTO `wp_postmeta` VALUES (176819,4771,'video_url','https://vimeo.com/629500653');
INSERT INTO `wp_postmeta` VALUES (176820,4771,'_video_url','field_630bc94871849');
INSERT INTO `wp_postmeta` VALUES (176821,4771,'our_differentiators_list','<ul>\r\n 	<li>A&amp;M DIG uses <strong>government data,</strong> ensuring it is <strong>reliable</strong> and updated on a consistent basis.</li>\r\n 	<li>A&amp;M DIG leverages <strong>A&amp;M operational and functional experts</strong> across industries who are on the ground and have first-hand <strong>insight</strong> into evolving market dynamics to determine additional data points needed to make the best investment decisions.</li>\r\n 	<li>A&amp;M DIG creates a <strong>customized dashboard</strong> that enables M&amp;A professionals to filter and sort through data such as <strong>company size, growth trajectory, company ownership</strong> and other meaningful data points determined by you to discover the best opportunities.</li>\r\n</ul>');
INSERT INTO `wp_postmeta` VALUES (176822,4771,'_our_differentiators_list','field_630bc9717184b');
