INSERT INTO `wp_wfissues` VALUES (23971,1635782099,1635782099,'new','wfPluginUpgrade',100,'a74ca6ecc820ce5f98b871c6fcb7a8b7','a74ca6ecc820ce5f98b871c6fcb7a8b7','The Plugin \"Advanced Custom Fields\" needs an upgrade (5.9.5 -> 5.10.2).','You need to upgrade \"Advanced Custom Fields\" to the newest version to ensure you have any security fixes the developer has released.','a:19:{s:4:\"Name\";s:22:\"Advanced Custom Fields\";s:9:\"PluginURI\";s:36:\"https://www.advancedcustomfields.com\";s:7:\"Version\";s:5:\"5.9.5\";s:11:\"Description\";s:151:\"Customize WordPress with powerful, professional and intuitive fields. <cite>By <a href=\"https://www.advancedcustomfields.com\">Elliot Condon</a>.</cite>\";s:6:\"Author\";s:64:\"<a href=\"https://www.advancedcustomfields.com\">Elliot Condon</a>\";s:9:\"AuthorURI\";s:36:\"https://www.advancedcustomfields.com\";s:10:\"TextDomain\";s:3:\"acf\";s:10:\"DomainPath\";s:5:\"/lang\";s:7:\"Network\";b:0;s:10:\"RequiresWP\";s:0:\"\";s:11:\"RequiresPHP\";s:0:\"\";s:5:\"Title\";s:73:\"<a href=\"https://www.advancedcustomfields.com\">Advanced Custom Fields</a>\";s:10:\"AuthorName\";s:13:\"Elliot Condon\";s:10:\"pluginFile\";s:80:\"/home/eo044zl56xul/public_html/wp-content/plugins/advanced-custom-fields/acf.php\";s:10:\"newVersion\";s:6:\"5.10.2\";s:4:\"slug\";s:22:\"advanced-custom-fields\";s:5:\"wpURL\";s:52:\"https://wordpress.org/plugins/advanced-custom-fields\";s:10:\"vulnerable\";b:1;s:17:\"vulnerabilityLink\";s:73:\"https://wpvulndb.com/vulnerabilities/f322619a-e85d-4931-8785-eb9cf30cef7f\";}');
INSERT INTO `wp_wfissues` VALUES (23972,1635782099,1635782099,'new','wfPluginUpgrade',50,'bba6f66255d6d96d4d24b035377ff6cf','bba6f66255d6d96d4d24b035377ff6cf','The Plugin \"Akismet Anti-Spam\" needs an upgrade (4.1.9 -> 4.2.1).','You need to upgrade \"Akismet Anti-Spam\" to the newest version to ensure you have any security fixes the developer has released.','a:18:{s:4:\"Name\";s:17:\"Akismet Anti-Spam\";s:9:\"PluginURI\";s:20:\"https://akismet.com/\";s:7:\"Version\";s:5:\"4.1.9\";s:11:\"Description\";s:363:\"Used by millions, Akismet is quite possibly the best way in the world to <strong>protect your blog from spam</strong>. It keeps your site protected even while you sleep. To get started: activate the Akismet plugin and then go to your Akismet Settings page to set up your API key. <cite>By <a href=\"https://automattic.com/wordpress-plugins/\">Automattic</a>.</cite>\";s:6:\"Author\";s:66:\"<a href=\"https://automattic.com/wordpress-plugins/\">Automattic</a>\";s:9:\"AuthorURI\";s:41:\"https://automattic.com/wordpress-plugins/\";s:10:\"TextDomain\";s:7:\"akismet\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:10:\"RequiresWP\";s:0:\"\";s:11:\"RequiresPHP\";s:0:\"\";s:5:\"Title\";s:52:\"<a href=\"https://akismet.com/\">Akismet Anti-Spam</a>\";s:10:\"AuthorName\";s:10:\"Automattic\";s:10:\"pluginFile\";s:69:\"/home/eo044zl56xul/public_html/wp-content/plugins/akismet/akismet.php\";s:10:\"newVersion\";s:5:\"4.2.1\";s:4:\"slug\";s:7:\"akismet\";s:5:\"wpURL\";s:37:\"https://wordpress.org/plugins/akismet\";s:10:\"vulnerable\";b:0;}');
INSERT INTO `wp_wfissues` VALUES (23935,1635720109,1635720109,'new','skippedPaths',25,'6fd0d290b978eab8027e6b79501ac149','6fd0d290b978eab8027e6b79501ac149','3 paths were skipped for the malware scan due to scan settings','The option \"Scan files outside your WordPress installation\" is off by default, which means 3 paths and their file(s) will not be scanned for malware or unauthorized changes. To continue skipping these paths, you may ignore this issue. Or to start scanning them, enable the option and subsequent scans will include them. Some paths may not be necessary to scan, so this is optional. <a href=\"https://www.wordfence.com/help/?query=scan-result-skipped-paths\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More<span class=\"screen-reader-text\"> (opens in new tab)</span></a><br><br>The paths skipped are ~/_, ~/eblast, and ~/pdf','a:0:{}');
INSERT INTO `wp_wfissues` VALUES (23970,1635782099,1635782099,'new','wfUpgrade',75,'24117975f6a30dcc10eb13acb08a1b7a','24117975f6a30dcc10eb13acb08a1b7a','Your WordPress version is out of date','WordPress version 5.8.1 is now available. Please upgrade immediately to get the latest security updates from WordPress.','a:2:{s:14:\"currentVersion\";s:5:\"5.7.2\";s:10:\"newVersion\";s:5:\"5.8.1\";}');
